package benchmark;
import bms.player.beatoraja.MainState;
import bms.player.beatoraja.TimerManager;
import bms.player.beatoraja.input.KeyboardQueueTestSupport;
import bms.player.beatoraja.skin.lua.TimerUtility;
import org.luaj.vm2.*;
import org.luaj.vm2.lib.*;
import org.openjdk.jmh.annotations.*;
import java.util.concurrent.TimeUnit;
@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations=2,time=500,timeUnit=TimeUnit.MILLISECONDS)
@Measurement(iterations=3,time=500,timeUnit=TimeUnit.MILLISECONDS)
@Fork(value=2,jvmArgsAppend={"-Xms512m","-Xmx512m"})
public class TimerOffValueBenchmark {
 @Param({"off","on"}) public String mode;
 private LuaValue observed, passive;
 @Setup public void setup() throws Exception {
  TestState state=KeyboardQueueTestSupport.allocate(TestState.class);
  Clock clock=new Clock();
  KeyboardQueueTestSupport.set(state,MainState.class,"timer",clock);
  LuaTable util=new LuaTable();new TimerUtility(state).export(util);
  final boolean on=mode.equals("on");
  observed=util.get("timer_observe_boolean").call(new ZeroArgFunction(){@Override public LuaValue call(){return LuaValue.valueOf(on);}});
  LuaValue bundle=util.get("new_passive_timer").call();
  passive=bundle.get("timer");if(on)bundle.get("turn_on").call();
  if(observed.call().tolong()!=(on?1234567890L:Long.MIN_VALUE))throw new AssertionError("observed");
  if(passive.call().tolong()!=(on?1234567890L:Long.MIN_VALUE))throw new AssertionError("passive");
 }
 @Benchmark public LuaValue observed() {return observed.call();}
 @Benchmark public LuaValue passive() {return passive.call();}
 public static class Clock extends TimerManager {@Override public long getNowMicroTime(){return 1234567890L;}}
 public static class TestState extends MainState {
  public TestState(){super(null,null);}
  @Override public void create(){}
  @Override public void render(){}
 }
}

